  Lemma ienv_transport_split : forall tp TSD CTX TH sb TOP BOT m m' W Wo Wi,
    IENV tp TSD CTX TH sb TOP BOT m -> munch W m m' -> wmono bsegs m m' ->
    (forall a n, disjoint_from Wo a n -> disjoint_from Wi a n -> disjoint_from W a n) ->
    out_img Wo ->
    65536 <= bv_unsigned tp + -88 -> bv_unsigned tp + 16 + 4 <= 6832128 -> 65536 <= TSD -> TSD + 8 <= 6832128 ->
    disjoint_from Wi (bv_unsigned tp + -88) 8 -> disjoint_from Wi TSD 8 -> disjoint_from Wi (bv_unsigned tp + 16) 4 ->
